const D = { energy: .55, scale: 1, density: .55, speed: 1, steam: .6, heat: .55, hue: 180, x: .42, y: .38, style: 'travertine', act: 'steady', seed: 0, alpha: 1 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const ho = P.hue - 180;
const L3 = (a, b, f) => [a[0] + (b[0]-a[0])*f, a[1] + (b[1]-a[1])*f, a[2] + (b[2]-a[2])*f];
const sh = c => [hw(c[0] + ho), c[1], c[2]];

const STY = {
  // white-cream travertine terraces, teal pools, warm microbial rims
  travertine:{ skT:[204,20,58], skB:[192,10,78], haze:[190,10,80], stone:[40,10,88], stoneS:[36,16,66],
               pool:[184,54,58], rim:[28,70,72], rim2:[54,66,74], steam:[190,6,96], grain:16, thermal:0 },
  // soft dawn: pink-gold steam, cool pools
  dawn:      { skT:[220,26,40], skB:[28,34,80], haze:[30,26,74], stone:[34,16,84], stoneS:[24,24,58],
               pool:[196,46,52], rim:[16,64,74], rim2:[44,60,78], steam:[26,20,96], grain:16, thermal:0 },
  // night nocturne: eerie steam, deep blue pools
  nocturne:  { skT:[232,50,10], skB:[214,32,26], haze:[214,24,30], stone:[210,16,44], stoneS:[214,24,28],
               pool:[196,58,34], rim:[10,50,44], rim2:[40,44,46], steam:[204,14,72], grain:12, thermal:0 },
  // ABSTRACTED thermal false-colour: pools as hot cores, ironbow
  thermal:   { skT:[250,58,6], skB:[250,42,12], haze:[250,34,14], stone:[268,40,20], stoneS:[262,44,14],
               pool:[40,90,99], rim:[16,92,88], rim2:[54,80,99], steam:[300,26,40], grain:5, thermal:1 },
  // ABSTRACTED sumi ink: tonal terraces + steam wash
  ink:       { skT:[30,5,84], skB:[30,3,74], haze:[30,3,78], stone:[30,4,84], stoneS:[30,7,58],
               pool:[30,6,48], rim:[30,10,40], rim2:[30,7,60], steam:[30,3,90], grain:28, thermal:0 }
};
const st = STY[P.style] || STY.travertine;

const en = Math.max(0, Math.min(1, P.energy));
const heat = Math.max(0, Math.min(1, P.heat));
const hzY = height * P.y;                          // horizon
const key = width + 'x' + height + '|' + P.style + '|' + P.seed + '|' + Math.round(P.hue) + '|' + P.scale.toFixed(2) + '|' + P.density.toFixed(2) + '|' + P.y.toFixed(3) + '|' + P.x.toFixed(3);

if (!S.sky || S.key !== key) {
  const W = Math.max(2, Math.ceil(width)), H = Math.max(2, Math.ceil(height));
  const mk = (w, h) => { const g = createGraphics(Math.max(2, Math.ceil(w)), Math.max(2, Math.ceil(h))); g.colorMode(g.HSB, 360, 100, 100, 100); return g; };
  if (S.terr) { S.terr.remove(); }
  S.sky = S.sky || 1; S.terr = mk(W, H);
  const g = S.terr; g.noStroke();
  const skT = sh(st.skT), skB = sh(st.skB), hazeC = sh(st.haze);
  const stoneC = sh(st.stone), stoneS = sh(st.stoneS), poolC = sh(st.pool), rimC = sh(st.rim), rim2C = sh(st.rim2);

  // sky
  for (let yy = 0; yy < Math.ceil(hzY); yy++) { const c = L3(skT, skB, Math.pow(yy / Math.max(1, hzY), .7)); g.fill(c[0], c[1], c[2]); g.rect(0, yy, W, 1); }
  // distant hillside base beyond the terraces
  g.fill(L3(stoneS, hazeC, .6)[0], L3(stoneS, hazeC, .6)[1], L3(stoneS, hazeC, .6)[2]);
  g.rect(0, hzY, W, H - hzY);

  // --- terrace bands from far (near horizon) to near (foreground) ---
  S.pools = [];
  const NT = Math.floor(6 + P.density * 6);
  for (let L = 0; L < NT; L++) {
    const near = L / (NT - 1);
    const haze = (1 - near) * (.5 + .35 * (1 - heat));
    const yTop = hzY + Math.pow(near, 1.4) * (H - hzY);
    const bandH = (H - hzY) * (.06 + near * .16) * P.scale / (1 + NT * .1);
    const cx = W * P.x + Math.sin(near * 3 + fr(L) * 6.3) * W * .06;
    const halfW = W * (.2 + near * .34);
    // the mineral shelf (front apron of travertine)
    const stC = L3(stoneC, hazeC, haze);
    const stSh = L3(stoneS, hazeC, haze);
    g.fill(stC[0], stC[1], stC[2], 100);
    g.rect(0, yTop, W, bandH * 2.2);
    // the pool sitting on the shelf
    const pTop = yTop + bandH * .25;
    const pC = L3(poolC, hazeC, haze * .7);
    g.fill(pC[0], pC[1], pC[2], 100);
    g.ellipse(cx, pTop, halfW * 2, bandH * 1.2);
    // microbial colour rings (orange/green) around the pool
    for (let r = 0; r < 3; r++) {
      const rc = r % 2 === 0 ? L3(rimC, hazeC, haze) : L3(rim2C, hazeC, haze);
      g.noFill(); g.strokeWeight(Math.max(1.2, bandH * .12) * (1 + r * .3));
      g.stroke(rc[0], rc[1] * (.4 + heat * .6), rc[2], (40 + 30 * heat) * (1 - r * .2));
      g.ellipse(cx, pTop, halfW * (2 + r * .3), bandH * (1.2 + r * .3));
    }
    g.noStroke();
    // scalloped rimstone dams along the front lip
    const nS = Math.floor(8 + near * 16);
    for (let s2 = 0; s2 < nS; s2++) {
      const sx = (s2 + .5) / nS * W;
      g.fill(stSh[0], stSh[1], Math.max(2, stSh[2] - 6), 70);
      g.arc(sx, yTop + bandH * 1.4, W / nS * 1.2, bandH * 1.1, 0, Math.PI);
      g.fill(stC[0], stC[1], Math.min(99, stC[2] + 6), 50);
      g.arc(sx, yTop + bandH * 1.35, W / nS * 1.0, bandH * .8, Math.PI, Math.PI * 2);
    }
    S.pools.push({ cx: cx, y: pTop, halfW: halfW, bandH: bandH, near: near, haze: haze, phase: fr(L * 7 + 3) * 6.283 });
  }
  S.key = key;
}

// ---------------- act ----------------
const sec = ((Math.floor(K.section) % 6) + 6) % 6;
const ACT = { steady: 1, surge: 1.3 + .5 * Math.sin(K.t * .12 + sec), cooling: .55 + .12 * Math.sin(K.t * .08) };
const steamAmt = Math.max(.15, (ACT[P.act] != null ? ACT[P.act] : 1)) * (P.steam + .2);

noStroke();
image(S.terr, 0, 0);

// ---------------- pool shimmer + specular sheen ----------------
const steamC = sh(st.steam), poolC = sh(st.pool);
for (const p of S.pools) {
  noFill();
  for (let i = 0; i < Math.floor(4 + p.near * 5); i++) {
    const f = i / 8;
    const ph = K.t * (.4 + f) * P.speed + p.phase;
    strokeWeight(Math.max(.5, u * .0014 * (.3 + p.near)));
    stroke(poolC[0], poolC[1] * .6, Math.min(99, poolC[2] + 20 + 20 * p.near), (16 + 24 * p.near) * (.4 + en) * (1 - p.haze));
    beginShape();
    for (let t = -1; t <= 1; t += .12) {
      const wob = Math.sin(t * 5 + ph) * p.bandH * .1;
      vertex(p.cx + t * p.halfW * .92, p.y - p.bandH * .2 + f * p.bandH * .5 + wob);
    }
    endShape();
  }
}
noStroke();

// ---------------- steam rising off the pools (broad motion carrier) ----------------
blendMode(SCREEN);
for (const p of S.pools) {
  const np = Math.floor((5 + p.near * 8) * (.4 + P.density));
  for (let i = 0; i < np; i++) {
    const life = ((K.t * (.04 + fr(i * 3 + Math.floor(p.cx) + 11) * .06) * P.speed * steamAmt + fr(i * 3 + Math.floor(p.cx) + 12)) % 1);
    const rise = Math.pow(life, .9);
    const sx = p.cx + (fr(i * 3 + Math.floor(p.cx) + 13) - .5) * p.halfW * 1.4 + Math.sin(K.t * (.3 + fr(i) * .5) + i + rise * 4) * u * .03 * (1 + rise);
    const sy = p.y - rise * u * (.14 + p.near * .22) * (1 + steamAmt * .4);
    const sr = u * (.02 + fr(i) * .04) * (.5 + rise * 2.5) * (.6 + P.steam);
    fill(steamC[0], steamC[1] * (1 - rise * .5), steamC[2], (14 * steamAmt) * (1 - Math.abs(life - .45) * 1.4) * (1 - p.haze * .5) * (.5 + en));
    ellipse(sx, sy, sr, sr * 1.1);
  }
}
blendMode(BLEND);

// bubbles / vent glints on the pools
if (!st.thermal) {
  blendMode(ADD);
  for (const p of S.pools) {
    const nb = Math.floor(2 + p.near * 4);
    for (let i = 0; i < nb; i++) {
      const life = ((K.t * (.3 + fr(i) * .4) * P.speed + fr(i * 3 + Math.floor(p.cx) + 21)) % 1);
      const bx = p.cx + (fr(i * 3 + 22) - .5) * p.halfW * 1.6;
      const by = p.y + (fr(i * 3 + 23) - .3) * p.bandH * .6;
      fill(steamC[0], steamC[1] * .4, steamC[2], 40 * (1 - life) * en);
      ellipse(bx, by, u * .004 * (1 + life), u * .004 * (1 + life));
    }
  }
  blendMode(BLEND);
}

// grain, vignette, alpha
if (st.grain > 6) {
  const ng2 = Math.floor(st.grain * 5);
  for (let i = 0; i < ng2; i++) {
    const gx = ((fr(i * 3 + 401) * width) + Math.sin(K.t * .01 + i) * u * .002 + width) % width;
    const gy = fr(i * 3 + 402) * height;
    fill(st.stone[0], st.stone[1] * .4, fr(i * 3 + 403) > .5 ? 92 : 10, 3 + fr(i) * 5);
    rect(gx, gy, u * .0016, u * .0016);
  }
}
for (let i = 0; i < 5; i++) {
  noFill(); strokeWeight(u * .05);
  stroke(sh(st.stoneS)[0], st.stoneS[1], 8, 16 * (1 - i * .17));
  rect(-u * .03 + i * u * .03, -u * .03 + i * u * .03, width + u * .06 - i * u * .06, height + u * .06 - i * u * .06);
}
noStroke();
if (P.alpha < 1) { fill(sh(st.stoneS)[0], st.stoneS[1] * .5, 8, (1 - P.alpha) * 100); rect(0, 0, width, height); }
blendMode(BLEND);
drawingContext.shadowBlur = 0;
